/**
 * Spike 5 T6: regenerates ts/drum/templates.ts (the fixed NMF templates) for the default config's spectrum params.
 *   npx tsx ts/drum/make_templates.ts        (from spikes/analysis, devcontainer; needs soundfonts/MuseScore_General.sf2)
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { specParams } from './classify';
import { DEFAULT_DRUM_CONFIG } from './config';
import { buildTemplates } from './templates_build';

const table = buildTemplates(specParams(DEFAULT_DRUM_CONFIG));
const body = [
  '// GENERATED by ts/drum/make_templates.ts (spike 5 T6) - do not edit. Fixed NMF templates of classify.ts from the',
  '// tuning kit A one-shots; regenerate when classify spectrum params (win hop melBands fminHz fmaxHz preFrames',
  '// postFrom postCount) or audio.sr change.',
  "import type { TemplateTable } from './classify';",
  '',
  `export const DRUM_TEMPLATES: TemplateTable = ${JSON.stringify(table)};`,
  '',
].join('\n');
const out = fileURLToPath(new URL('./templates.ts', import.meta.url));
writeFileSync(out, body);
console.log(`wrote ${out}: ${table.columns.length} columns x ${table.params.melBands} bands, ${body.length} bytes`);
